{
  "headline": "FDA's records trace our supply to a plant classified OAI 85 days before the shortage posting",
  "headline_cites": ["D4"],
  "sentences": [
    {
      "text": "FDA's shortage history shows oxytocin was first posted on 2022-09-23 and is now resolved as of 2026-10-21.",
      "cites": ["D10"]
    },
    {
      "text": "An FDA inspection of Fresenius Kabi USA, LLC (FEI 1450022) ended 2022-06-30 and was classified OAI, with the classification letter dated 2024-04-30, 85 days before the shortage posting.",
      "cites": ["D4", "E12"]
    },
    {
      "text": "A prior inspection of the same plant ended 2020-05-18 and was also classified OAI, with the letter dated 2024-05-22, 858 days before the posting.",
      "cites": ["D3", "E11"]
    },
    {
      "text": "Later inspections of that plant in 2023-08-24 and 2023-10-13 were classified VAI, occurring 335 and 385 days after the posting.",
      "cites": ["D5", "D6", "E13", "E26"]
    },
    {
      "text": "A second Fresenius Kabi plant (FEI 3001833549) received OAI classifications in 2011-07-08 and 2013-01-11, with letters dated 2017-12-28 and 2013-04-11, respectively.",
      "cites": ["E17", "E20"]
    },
    {
      "text": "The preferred alternative is oxytocin 10 units/mL from Par Health USA, LLC, approved by Sam Rivera, MD on 2026-04-16, requiring dose recalculation and pharmacist verification.",
      "cites": ["D11", "E5", "E29"]
    },
    {
      "text": "A second alternative from Fresenius Kabi USA, LLC was approved by Riley Brooks, PharmD on 2026-01-24, also requiring dose recalculation and pharmacist verification.",
      "cites": ["D12", "E14", "E30"]
    }
  ]
}
